# Application/check of benchmark/baseline/attempt-ledger-0150.json over finite SYNTHETIC event traces.
# Author consistency only. No provider, runner, scorer, historical checker or product code is executed; no real receipt exists.
import json, hashlib, pathlib, datetime, collections
rd = lambda p: pathlib.Path(p).read_bytes()
sha = lambda b: hashlib.sha256(b).hexdigest()
canon = lambda o: json.dumps(o, sort_keys=True, separators=(',', ':'), ensure_ascii=False).encode()
CB = rd('benchmark/baseline/attempt-ledger-0150.json'); C = json.loads(CB)
EB = rd('.session/artifacts/attempt-ledger-expectations-0150.json'); E = json.loads(EB)
RB = rd('.session/inputs/685-attempt-policy-independent-expectations-0149.json'); R = json.loads(RB)
PB = rd('benchmark/baseline/attempt-policy-0148.json'); P = json.loads(PB)
EV = json.loads(rd('benchmark/attempt-evidence-0143.json'))['contract']['required_evidence']
ES = {s['id']: s for s in E['scenarios']}
RC = {c['id']: c for c in R['cases']}

CASE = 'synthetic:review-case'
PLAN = [('A-N', 'synthetic:review-pair-A', 'synthetic:01-N', 'no-tool'), ('A-T', 'synthetic:review-pair-A', 'synthetic:71-T', 'tool'),
        ('B-N', 'synthetic:review-pair-B', 'synthetic:02-N', 'no-tool'), ('B-T', 'synthetic:review-pair-B', 'synthetic:09-T', 'tool')]
ORDER = [p[0] for p in PLAN]
IDENT = {p[0]: dict(record_id=p[0], case_id=CASE, pair_id=p[1], repetition_id=p[2], arm=p[3]) for p in PLAN}
COMPS = {'A': ('A-N', 'A-T'), 'B': ('B-N', 'B-T')}
LEDGER = 'synthetic:ledger-0150'; RECEIPT = sha(b'synthetic receipt - not a real receipt')
PREC = ['hard_evidence_failure', 'settings_drift', 'budget']
STATE = {'hard_evidence_failure': 'stopped_hard_failure', 'settings_drift': 'stopped_settings_drift', 'budget': 'stopped_budget'}
RECOV_OK = {'recovery_opened', 'evidence_gap_recorded', 'stop_recorded', 'plan_terminal', 'final_audit', 'submission_quarantined'}
POST_OK = {'submission_quarantined', 'evidence_gap_recorded', 'delivery_retained', 'delivery_interpreted', 'usage_reconciled', 'final_audit', 'audit_revision'}
HANDLED = {'preflight_result', 'reservation_made', 'dispatch_recorded', 'delivery_retained', 'delivery_interpreted', 'usage_reconciled', 'slot_closed',
           'stop_recorded', 'plan_terminal', 'final_audit', 'audit_revision', 'submission_quarantined', 'evidence_gap_recorded', 'recovery_opened'}
T0 = datetime.datetime(2026, 11, 15, 21, 0, 0)
RESP = lambda s, tag='': json.dumps({'claims': [{'id': 'D1', 'slot': s, 'tag': tag}]}, sort_keys=True).encode()
ERR = b'{"error":"synthetic failure"}'
OKPOST = {'settings_match': True, 'model_ok': True, 'evidence_ok': True}


class B:
    def __init__(s, auth='stipulated_synthetic'):
        s.ev = []; s.auth = auth; s.seq = 0; s.prev = None; s.t = 100; s.o = 0; s.dl = 0

    def add(s, typ, payload=None, slot=None, att=None, dlv=None, order=None, seg='main', persist='acknowledged', receipt=RECEIPT):
        s.t += 1
        e = {'ledger_id': LEDGER, 'receipt_sha256': receipt, 'seq': s.seq + 1, 'segment': seg, 'event_type': typ,
             'event_utc': (T0 + datetime.timedelta(seconds=s.t)).strftime('%Y-%m-%dT%H:%M:%SZ'), 'prev_event_sha256': s.prev,
             'persistence': persist, 'producer': {'id': 'synthetic-producer', 'version': '0', 'authority_class': s.auth},
             'slot': IDENT.get(slot), 'slot_ref': slot, 'attempt_id': att, 'attempt_order': order, 'delivery_id': dlv,
             'evidence_refs': [], 'payload': payload or {}}
        e['event_sha256'] = sha(canon(e)); s.seq += 1; s.prev = e['event_sha256']; s.ev.append(e); return e

    def fork(s, n):
        s.seq = n; s.prev = [e for e in s.ev if e['seq'] == n and e['segment'] == 'main'][0]['event_sha256']

    def pre(s, outcome='ready'): s.add('preflight_result', {'outcome': outcome, 'receipt_status': 'stipulated_synthetic'})
    def reserve(s, slot): s.add('reservation_made', {'gate': dict(bindings_match=True, model_window_ok=True, evidence_ok=True, reservation_covers=True), 'reserved': {'tokens': 1000, 'time_s': 60, 'calls': 1}}, slot=slot)

    def dispatch(s, slot, ack=True, order=None):
        s.o += 1; a = 'synthetic:attempt-%d' % s.o; req = ('request for ' + slot).encode()
        s.add('dispatch_recorded', {'request_sha256': sha(req), 'request_size': len(req)}, slot=slot, att=a, order=order or s.o, persist='acknowledged' if ack else 'unacknowledged'); return a

    def deliver(s, slot, a, kind, resp, missing=(), order=None, bad=False):
        assert all(k in EV for k in missing)
        s.dl += 1; d = 'synthetic:delivery-%d' % s.dl
        r = {'presence': 'absent', 'hex': None, 'size': None, 'sha256': None} if resp is None else {'presence': 'present', 'hex': resp.hex(), 'size': len(resp), 'sha256': sha(resp + b'x' if bad else resp)}
        s.add('delivery_retained', {'kind': kind, 'response': r, 'evidence_missing': list(missing)}, slot=slot, att=a, dlv=d, order=order); return d

    def interp(s, slot, a, d, cls='ok', legacy=True, proof='none', decision=None, post=None):
        s.add('delivery_interpreted', {'answer_class': cls, 'legacy_valid': legacy, 'proof': proof, 'decision': decision, 'postdispatch': post or OKPOST}, slot=slot, att=a, dlv=d)

    def usage(s, slot, a, known=True, exh=False):
        s.add('usage_reconciled', {'usage_known': known, 'tokens_in': 100 if known else None, 'tokens_out': 50 if known else None, 'exhausted': exh, 'cost': None}, slot=slot, att=a)

    def close(s, slot, cls): s.add('slot_closed', {'classification': cls}, slot=slot)
    def stop(s, causes, gate='postdispatch', seg='main', primary=None): s.add('stop_recorded', {'gate': gate, 'causes': causes, 'primary': primary or min(causes, key=PREC.index)}, seg=seg)
    def term(s, state, seg='main'): s.add('plan_terminal', {'state': state}, seg=seg)
    def audit(s, rev, sc, seg='main'): s.add('final_audit' if rev == 0 else 'audit_revision', {'revision': rev, 'structural_comparisons': sc, 'trigger_seqs': []}, seg=seg)

    def cycle(s, slot, resp='default', cls='ok', legacy=True, dec='ROW', close='attempted_eligible', missing=(), known=True, exh=False, post=None, mid=None):
        if resp == 'default': resp = RESP(slot)
        s.reserve(slot); a = s.dispatch(slot); d = s.deliver(slot, a, 'dispatched', resp, missing)
        s.interp(slot, a, d, cls, legacy, 'none', dec, post); s.usage(slot, a, known, exh)
        if mid: mid(a, d, resp)
        if close: s.close(slot, close)
        return a, d

    def redeliver(s, slot, a, resp, proof, dec):
        d = s.deliver(slot, a, 'redelivery', resp); s.interp(slot, a, d, 'ok', True, proof, dec)
        if dec == 'QUARANTINE': s.add('submission_quarantined', {'reason': 'conflicting same-ID bytes'}, slot=slot, att=a, dlv=d)

    def unsol(s, slot, resp, dec='ROW_UNRESOLVED'):
        s.o += 1; a = 'synthetic:attempt-%d' % s.o; d = s.deliver(slot, a, 'unsolicited', resp, order=s.o)
        s.interp(slot, a, d, 'ok', True, 'none', dec); s.usage(slot, a); return a


def parse_state(r):
    if r['presence'] == 'absent': return 'absent'
    b = bytes.fromhex(r['hex'])
    if not b: return 'empty'
    try: t = b.decode('utf-8')
    except UnicodeDecodeError: return 'invalid_utf8'
    try: json.loads(t)
    except ValueError: return 'malformed_json'
    return 'parseable_json'


def decide(d, proof):
    if not d['repr']: return 'QUARANTINE'
    k = d['kind']
    if k == 'redelivery':
        if d['rel'] in ('conflicting', 'no_prior'): return 'QUARANTINE'
        return 'DELIVERY_ONLY' if proof in ('stipulated_synthetic', 'independently_verified') else 'DELIVERY_ONLY_UNPROVED'
    if k == 'unsolicited': return 'ROW_UNRESOLVED' if d['complete'] else 'QUARANTINE'
    return 'ROW' if d['complete'] else 'BUNDLE_NO_ROW'


dec = lambda d: d['decision'] or decide(d, 'none')


def run(ev):
    V = []; main = [e for e in ev if e['segment'] == 'main']; rec = [e for e in ev if e['segment'] == 'recovery']
    ok = []; brk = None; ps = 0; ph = None; pu = None
    hashed = lambda e: sha(canon({k: v for k, v in e.items() if k != 'event_sha256'}))
    for e in main:
        r = None
        if e['ledger_id'] != LEDGER or e['receipt_sha256'] != RECEIPT: r = 'V01'
        elif e['seq'] != ps + 1: r = 'V02'
        elif e['prev_event_sha256'] != ph: r = 'V03'
        elif hashed(e) != e['event_sha256']: r = 'V04'
        elif pu and e['event_utc'] < pu: r = 'V05'
        elif e['persistence'] != 'acknowledged': r = 'V06'
        if r: brk = (e['seq'], r); V.append(brk); break
        ok.append(e); ps = e['seq']; ph = e['event_sha256']; pu = e['event_utc']
    suspect = main[len(ok):]; last_seq = ps; chain = list(ok)
    for e in rec:
        if e['seq'] != ps + 1 or e['prev_event_sha256'] != ph or hashed(e) != e['event_sha256'] or e['persistence'] != 'acknowledged':
            V.append((e['seq'], 'V02-V06(recovery)')); break
        chain.append(e); ps = e['seq']; ph = e['event_sha256']
    sus = {e['slot_ref'] for e in suspect if e['slot_ref']}
    S = dict(pre=None, stop=None, term=None, open=None, res=None, nxt=0, att={}, dl={}, disp=[], closed={}, usage={}, gaps=set(), quar=0, audits=[], claims=0, tsnap=None)

    def closure(sl):
        at = [x for x, v in S['att'].items() if v['slot'] == sl]; ds = [d for d in S['dl'].values() if d['slot'] == sl]
        mn = [d for d in ds if d['kind'] == 'dispatched']
        if len(at) != 1 or not mn or sl in S['gaps']: return 'unresolved'
        if any(dec(d) in ('DELIVERY_ONLY_UNPROVED', 'QUARANTINE') for d in ds): return 'unresolved'
        m = mn[0]
        if dec(m) != 'ROW': return 'unresolved'
        i = m['interp']
        if not i: return 'attempted_ineligible'
        u = S['usage'].get(m['att'])
        good = i['answer_class'] == 'ok' and i['legacy_valid'] and m['parse'] == 'parseable_json' and all(i['postdispatch'].values()) and not (u and u['exh'])
        return 'attempted_eligible' if good else 'attempted_ineligible'

    def inv():
        at = S['att']; ds = list(S['dl'].values()); ref = {v['slot'] for v in at.values()}
        miss = [s for s in ORDER if s not in ref]
        ind = [s for s in ORDER if s in sus and S['closed'].get(s) != 'attempted_eligible']
        unst = [s for s in ORDER if s not in S['disp'] and s not in ind]
        un = set(ind)
        for s in ORDER:
            a_ = [x for x, v in at.items() if v['slot'] == s]
            if S['closed'].get(s) == 'unresolved' or len(a_) >= 2 or (a_ and s not in S['disp']) or s in S['gaps']: un.add(s)
            if any(dec(d) in ('DELIVERY_ONLY_UNPROVED', 'QUARANTINE') for d in ds if d['slot'] == s): un.add(s)
            if S['term'] and s in S['disp'] and s not in S['closed']: un.add(s)
        inel = set(un) | {s for s, c in S['closed'].items() if c != 'attempted_eligible'}
        st = sum(1 for x, y in COMPS.values() if all(S['closed'].get(z) == 'attempted_eligible' and z not in un for z in (x, y)))
        return dict(planned=len(ORDER), dispatched=[s for s in ORDER if s in S['disp']], authorized_dispatches=len(S['disp']), retained_attempts=len(at),
                    deliveries=len(ds), missing=miss, unstarted=unst, indeterminate=ind, ineligible=sorted(inel), unresolved=sorted(un), structural=st)

    def derive():
        if S['pre'] == 'blocked': return 'blocked_preflight'
        if S['stop']: return STATE[S['stop']['primary']]
        i = inv()
        return 'finished_complete' if all(s in S['closed'] for s in ORDER) and i['structural'] == len(COMPS) and not i['unresolved'] else 'finished_incomplete'

    hardstop = lambda: S['stop'] and 'hard_evidence_failure' in S['stop']['causes']
    for e in chain:
        t = e['event_type']; sl = e['slot_ref']; a = e['attempt_id']; p = e['payload']; q = e['seq']
        bad = lambda r: V.append((q, r))
