        if e['segment'] == 'recovery' and t not in RECOV_OK: bad('V13'); continue
        if S['term'] and t not in POST_OK: bad('V17'); continue
        if S['term'] and t == 'delivery_retained' and p['kind'] == 'dispatched': bad('V17'); continue
        if t == 'preflight_result': S['pre'] = p['outcome']
        elif t == 'reservation_made':
            rs = []
            if S['pre'] != 'ready': rs.append('V01')
            if S['stop']: rs.append('V18')
            if S['open']: rs.append('V08')
            if S['nxt'] >= len(ORDER) or ORDER[S['nxt']] != sl: rs.append('V07')
            if any(not x['known'] for x in S['usage'].values()) and not hardstop(): rs.append('V28')
            if not all(p['gate'].values()): rs.append('V09')
            if rs: [bad(r) for r in rs]; continue
            S['open'] = sl; S['res'] = sl
        elif t == 'dispatch_recorded':
            rs = []
            if S['pre'] != 'ready': rs.append('V01')
            if S['stop']: rs.append('V18')
            if S['open'] and S['open'] != sl: rs.append('V08')
            if S['nxt'] >= len(ORDER) or ORDER[S['nxt']] != sl: rs.append('V07')
            if S['res'] != sl: rs.append('V09')
            if a in S['att'] or (S['att'] and (e['attempt_order'] or 0) <= max(x['order'] for x in S['att'].values())): rs.append('V10')
            if rs: [bad(r) for r in rs]; continue
            S['att'][a] = dict(slot=sl, order=e['attempt_order'], kind='dispatched'); S['disp'].append(sl)
        elif t == 'delivery_retained':
            k = p['kind']; r = p['response']
            if r['presence'] == 'present':
                b = bytes.fromhex(r['hex'])
                if len(b) != r['size'] or sha(b) != r['sha256']: bad('V12'); continue
            if k == 'dispatched' and not (S['open'] == sl and a in S['att'] and S['att'][a]['slot'] == sl): bad('V23'); continue
            if k == 'unsolicited':
                if a in S['att'] or (S['att'] and (e['attempt_order'] or 0) <= max(x['order'] for x in S['att'].values())): bad('V10'); continue
                S['att'][a] = dict(slot=sl, order=e['attempt_order'], kind='unsolicited')
            prior = [d for d in S['dl'].values() if d['att'] == a and d['kind'] != 'redelivery']; rel = 'n/a'
            if k == 'redelivery': rel = 'no_prior' if not prior else ('identical' if (prior[0]['sha'], prior[0]['pres']) == (r['sha256'], r['presence']) else 'conflicting')
            S['dl'][e['delivery_id']] = dict(att=a, slot=sl, kind=k, rel=rel, sha=r['sha256'], pres=r['presence'], parse=parse_state(r), complete=not p['evidence_missing'],
                                             repr=(sl in IDENT and e['slot'] == IDENT[sl]), seq=q, decision=None, interp=None, proof='none')
        elif t == 'delivery_interpreted':
            d = S['dl'].get(e['delivery_id'])
            if not d or d['seq'] >= q: bad('V11'); continue
            pr = 'none' if p['proof'] == 'independently_verified' else p['proof']
            if p['proof'] == 'independently_verified': S['claims'] += 1
            dc = decide(d, pr)
            if p['decision'] != dc: bad('V25')
            d['decision'] = dc; d['interp'] = p; d['proof'] = pr
        elif t == 'usage_reconciled':
            if a in S['usage']: bad('V24'); continue
            S['usage'][a] = dict(known=p['usage_known'], exh=p['exhausted'])
        elif t == 'slot_closed':
            if S['open'] != sl: bad('V15'); continue
            c = closure(sl)
            if p['classification'] != c: bad('V15')
            S['closed'][sl] = c; S['open'] = None; S['res'] = None; S['nxt'] += 1
        elif t == 'stop_recorded':
            if S['stop']: bad('V26'); continue
            pm = min(p['causes'], key=PREC.index)
            if p['primary'] != pm: bad('V27')
            S['stop'] = dict(causes=p['causes'], primary=pm, seq=q)
        elif t == 'plan_terminal':
            if S['term']: bad('V20'); continue
            if e['segment'] == 'main' and S['open']: bad('V16'); continue
            st = derive()
            if p['state'] != st: bad('V14')
            if e['segment'] == 'recovery' and p['state'] != 'stopped_hard_failure': bad('V13')
            if any(not x['known'] for x in S['usage'].values()) and not hardstop(): bad('V28')
            S['term'] = dict(state=st, seq=q); S['tsnap'] = inv()
        elif t in ('final_audit', 'audit_revision'):
            rev = p['revision']
            if not S['term']: bad('V17'); continue
            if rev != len(S['audits']) or (t == 'final_audit') != (rev == 0): bad('V19'); continue
            i = inv()
            if p['structural_comparisons'] != i['structural']: bad('V19')
            S['audits'].append(dict(rev=rev, declared=p['structural_comparisons'], computed=i['structural'], seq=q))
        elif t == 'submission_quarantined': S['quar'] += 1
        elif t == 'evidence_gap_recorded':
            if sl: S['gaps'].add(sl)
        elif t == 'recovery_opened':
            if p['last_verified_seq'] != last_seq: bad('V21'); break
    head = inv()
