    decs += ['BUNDLE_NO_ROW' for s in ORDER if s in S['disp'] and not any(d['slot'] == s and d['kind'] == 'dispatched' for d in S['dl'].values())]
    decs += ['NONE' for s in ORDER if s in head['indeterminate']]
    return dict(V=V, brk=brk, head=head, tsnap=S['tsnap'], term_state=S['term']['state'] if S['term'] else None, stop_causes=S['stop']['causes'] if S['stop'] else [],
                primary=S['stop']['primary'] if S['stop'] else None, decisions=decs, revs=sum(1 for x in S['audits'] if x['rev'] >= 1), claims=S['claims'],
                charged=len(S['usage']), quarantined=S['quar'], parse=dict(collections.Counter(d['parse'] for d in S['dl'].values())),
                audits=S['audits'], rules=sorted({r for _, r in V}))


