def cmp(res, es, r5, over):
    m = []
    def chk(f, exp, got):
        base = f.split('.')[-1]
        if base in SETF and isinstance(exp, list): exp, got = sorted(exp), sorted(got)
        if exp != got: m.append(dict(field=f, expected=exp, got=got))
    h = res['head']; ts = res['tsnap']
    for k, v in (es or {}).items():
        if k == 'decisions': chk(k, v, res['decisions'])
        elif k == 'stop_causes': chk(k, v, res['stop_causes'])
        elif k == 'terminal': chk(k, v, res['term_state'])
        elif k == 'audit_revisions_after_terminal': chk(k, v, res['revs'])
        elif k == 'completion_at_terminal': chk(k, v, ts['structural'] if ts else None)
        elif k == 'completion_at_head': chk(k, v, h['structural'])
        elif k == 'terminal_history_unchanged': chk(k, v, bool(ts) and res['term_state'] == es['terminal'])
        elif k == 'primary_cause': chk(k, v, res['primary'])
        elif k == 'dispatch_events': chk(k, v, h['authorized_dispatches'])
        elif k == 'inventory':
            for kk, vv in v.items(): chk('inventory.' + kk, vv, h[MAP.get(kk, kk)])
        elif k == 'integrity': chk(k, v, 'broken' if res['brk'] else 'intact')
        elif k == 'operational_terminal_claimed': chk(k, v, res['term_state'] is not None)
        elif k == 'accepted_independent_claims': chk(k, v, 0)
        elif k == 'rejected_independent_claims_min': chk(k, True, res['claims'] >= v)
    if r5:
        x = dict(r5['expected']); x.update(over)
        for k, v in x.items():
            if k == 'terminal': chk('685.terminal', v, res['term_state'])
            elif k in ('authorized_dispatches', 'deliveries', 'retained_attempts', 'structural_comparisons') and isinstance(v, int): chk('685.' + k, v, h[MAP.get(k, k)])
            elif k in ('missing', 'unstarted', 'ineligible', 'unresolved') and isinstance(v, list): chk('685.' + k, v, h[k])
    return m


